@Test
public void testDevianceTermValues() {
    Assert.assertEquals(10 * FastMath.log(2.0) - 5, SaddlePointExpansion.getDeviancePart(10, 5), 1e-12);
    Assert.assertEquals(20 * FastMath.log(20.0 / 19.0) - 1, SaddlePointExpansion.getDeviancePart(20, 19), 1e-12);
}
